#include <vector>
#include <string>
#include <cstddef>
#include <omp.h>

struct Book {
   std::string title;
   int pages;
};

size_t findLastShortBook(std::vector<Book> const& books) {
    const std::size_t n = books.size();
    if (n == 0) return n;

    std::size_t best = n; // n means "not found"

    #pragma omp parallel
    {
        std::size_t local_best = n;

        #pragma omp for nowait
        for (std::size_t i = 0; i < n; ++i) {
            if (books[i].pages < 100) {
                if (local_best == n || i > local_best) local_best = i;
            }
        }

        #pragma omp critical
        {
            if (local_best != n) {
                if (best == n || local_best > best) best = local_best;
            }
        }
    }

    return best;
}
